  ctx.save(); ctx.globalAlpha = .85; ctx.fillStyle = 'rgba(14,5,40,.7)'; ctx.beginPath(); ctx.roundRect(W - 188, 100, 168, 44 + lines.length * 22, 14); ctx.fill();
  txt('MODO TREINO', W - 104, 108, 15, '#ffb340', 'center', 900);
