    ctx.save(); if (f) { ctx.shadowColor = cd.c; ctx.shadowBlur = 30; }
    UI.panel(x, y, cw, h, { fill: f ? 'rgba(50,28,120,.85)' : 'rgba(20,8,55,.75)', stroke: f ? cd.c : 'rgba(190,160,255,.3)', r: 22 }); ctx.restore();
