    ctx.restore();
    UI.wrap(cd.name, x + cw / 2, y + 150, cw - 30, 26, 21, '#fff', 'center');
    cd.lines.forEach((l, k) => UI.wrap(l, x + cw / 2, y + 232 + k * 74, cw - 36, 22, 15, '#cdb8ff', 'center'));
