    // brilhos de estrela que piscam no logo
    ctx.globalCompositeOperation = 'lighter'; const k = Math.floor(t * .9), ph = t * .9 - k, sx = X0 + 40 + hsh(k) * 700, sy = Y0 - 80 + hsh(k + 9) * 70, a = Math.sin(ph * Math.PI);
