      if (bo && bo.targetable()) { const bx = bo.x + rand(-60, 60); G.parts.push({ k: 'bolt', x: bx, y: 0, x2: bx, y2: bo.y + 30, vx: 0, vy: 0, life: .2, max: .2, r: 3, c: '#e8fbff', drag: 1 }); bo.damage(d * .6); }
