  ctx.beginPath(); if (talk) ctx.ellipse(0, 34, 12, 5 + Math.abs(Math.sin(t * 14)) * 5, 0, 0, TAU); else ctx.arc(0, 28, 14, .2, Math.PI - .2); ctx.stroke();
