    for (let i = 0; i < n; i++) { const d = ((i - gap + n) % n); if (d < 4) continue; const a = i / n * TAU; ebullet(cx + Math.cos(a) * R, cy + Math.sin(a) * R, a + Math.PI, 125 + ph * 12, { r: 6, life: 6 }); }
