    UI.panel(x, y, w, h, { r: 16, fill: eq ? 'rgba(60,34,140,.88)' : UI.focus(bid) ? 'rgba(40,20,100,.85)' : 'rgba(20,8,55,.75)', stroke: eq ? '#ffd36a' : 'rgba(190,160,255,.3)' });
