Visual30.applyFilters = function () { const n = (Save.data.settings && Save.data.settings.cb) || 0; cv.style.filter = ((n ? 'url(#cb' + n + ') contrast(1.12) saturate(1.15) ' : '') + PF[Visual30.pf][1]).trim(); };
