      for (let q = 1; q < 14; q++) { const [tx, ty] = P(Math.max(0, k - q * .012)); ctx.save(); ctx.globalCompositeOperation = 'lighter'; drawGlow(tx, ty, 26 - q * 1.4, '#c8a0ff', .5 - q * .035); ctx.restore(); }
