const C4 = { cam: { x: 0, y: 0, z: 1 } };
const h4 = n => { const s = Math.sin(n * 127.1 + 311.7) * 43758.5453; return s - Math.floor(s); };
const cl4 = (x, a = 0, b = 1) => Math.max(a, Math.min(b, x));
