      for (let pass = 0; pass < 2; pass++) { ctx.beginPath(); T.pts.forEach((p, k) => k ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y)); ctx.strokeStyle = pass ? col : 'rgba(10,0,25,.75)'; ctx.lineWidth = pass ? 3 : 7; ctx.globalAlpha = pass ? .85 : 1; ctx.stroke(); }
