    if (s === 'clear' && !G.rush && !G.practice) { d.adapt.deaths[G.stageIdx] = 0; if (G.stats && G.stats.hits === 0) d.adapt.nohit[G.stageIdx] = (d.adapt.nohit[G.stageIdx] || 0) + 1; else d.adapt.nohit[G.stageIdx] = 0; msn().clears++; }
