  const mk = k => { const e = { k, t: 0 }; if (k === 'cover') e.pil = [0, 1, 2].map(i => ({ x: 240 + i * 400, y: 430 + (i % 2) * 40, w: 78, h: 96, hp: 18, ph: i * 2 })); if (k === 'lanes') { e.cd = 3; e.col = []; } return e; };
